/** A snapshot an extension sends after each render: everything it shows in the notch, its drop zones and its Settings page. */
export interface Snapshot {
  protocolVersion: 1;
  type: "snapshot";
  extensionID: string;
  /** Increases with every snapshot from the same runner. */
  revision: number;
  surfaces: Surface[];
  settings?: UINode;
  /** Where files, links and text dragged onto the notch can go. The app draws them during a drag from the last snapshot. */
  drops?: DropZone[];
}

export interface Surface {
  id: string;
  kind: SurfaceKind;
  title: string;
  initialView: Presentation;
  phase: SurfacePhase;
  compact?: CompactContent;
  expanded: UINode;
  peek?: PeekContent;
  tile?: TileContent;
  idlePreview?: boolean;
}

export type SurfaceKind = "activity" | "prompt";

export type Presentation = "compact" | "expanded";

export type SurfacePhase = "active" | "paused" | "completed" | "pending";

export interface CompactContent {
  leading: UINode[];
  trailing: UINode[];
}

/** A short announcement. A new id announces a new event; ordinary snapshots keep the same id. */
export interface PeekContent {
  /** Change for each new event; keep stable during routine renders. */
  id: string;
  text: string;
  duration: number;
}

/** The activity's tile in Home. Readings only: no buttons or fields, the whole tile opens the activity. Without one, Home builds the tile from compact and title. */
export interface TileContent {
  size: TileSize;
  content: UINode[];
}

/** small fills one cell of Home's four-column grid, wide fills two. The user can change it. */
export type TileSize = "small" | "wide";

export interface UINode {
  id: string;
  type: NodeType;
  props: NodeProps;
  children: UINode[];
}

export type NodeType = "column" | "row" | "text" | "symbol" | "progress" | "button" | "textField" | "artwork" | "waveform" | "player" | "spacer" | "divider" | "toggle" | "section" | "listItem" | "badge" | "picker" | "value" | "ring" | "fileItem" | "fileGrid";

export interface NodeProps {
  text?: string;
  name?: string;
  tone?: Tone;
  size?: TextSize;
  /** Progress or a Ring's fill, from zero to one. */
  value?: number;
  action?: string;
  placeholder?: string;
  disabled?: boolean;
  source?: string;
  media?: NowPlayingState;
  /** Secondary line: list item subtitle or section footer. */
  detail?: string;
  /** What a Value's number counts, drawn small beside it: min, %, mmhg. */
  unit?: string;
  spacing?: Spacing;
  align?: Alignment;
  /** Picker choices; `selection` holds the chosen value. */
  options?: PickerOption[];
  selection?: string;
  /** What VoiceOver says for a symbol, an icon-only button, a progress bar or a field. */
  label?: string;
  /** For `fileItem`. */
  file?: FileHandle;
  /** For `fileGrid`. */
  files?: FileHandle[];
  /** For `fileGrid`: the ids of the selected files. */
  selected?: string[];
  /** For `listItem`: text or a link that drags out of the row to any app. */
  drag?: string;
  /** For `fileGrid`: each file's menu has Remove, which the extension handles. */
  removable?: boolean;
}

export type Tone = "primary" | "secondary" | "accent" | "success" | "warning" | "danger";

export type TextSize = "caption" | "body" | "headline" | "title" | "timer";

export type Spacing = "none" | "tight" | "regular" | "loose";

export type Alignment = "start" | "center" | "end";

export interface PickerOption {
  value: string;
  label: string;
}

export interface NowPlayingState {
  id: string;
  eventID: string;
  player: string;
  playerName?: string;
  title: string;
  artist: string;
  album: string;
  /** Bounded JPEG/PNG data or an https URL on a host the extension lists in `imageHosts`. */
  artwork?: string;
  duration: number;
  position: number;
  isPlaying: boolean;
  volume: number;
  shuffle: boolean;
  repeating: boolean;
  /** Seconds since 1970 when `position` was read. */
  updatedAt: number;
}

/** A tap, toggle or text the user sent to an extension. */
export interface UserEvent {
  protocolVersion: 1;
  type: "event";
  action: string;
  value?: string;
}

/** A target for a drag: what happens, what it accepts, and the action that receives the dropped items. */
export interface DropZone {
  id: string;
  title: string;
  /** An SF Symbol name. */
  icon?: string;
  /** Uniform type identifiers. The zone shows when every dragged item conforms to one of them. */
  accepts: string[];
  /** Whether it takes more than one item at a time. */
  multiple?: boolean;
  /** The event action that receives the items as a JSON array of DropItem in `value`. */
  action: string;
  /** An activity of this extension to open after a drop, so the person can act on what they dropped. It stays open until they close it. */
  opens?: string;
}

/** A file the person dropped, as the extension sees it: never a path. The app keeps the bookmark behind `id`. */
export interface FileHandle {
  id: string;
  name: string;
  /** Its uniform type identifier. */
  type: string;
  size: number;
  kind: FileKind;
}

export type FileKind = "file" | "folder";

/** One thing dropped on a zone: a file, a link or text. */
export interface DropItem {
  kind: DropItemKind;
  file?: FileHandle;
  url?: string;
  title?: string;
  text?: string;
}

export type DropItemKind = "file" | "url" | "text";

export type JSONValue = null | boolean | number | string | JSONValue[] | { [key: string]: JSONValue };

export interface ConnectionCommand {
  protocolVersion: 1;
  type: "connectionCommand";
  extensionID: string;
  requestID: string;
  /** A connection declared in the manifest; empty for operations the app answers itself (fetch, secrets, openURL). */
  connectionID: string;
  operation: ConnectionOperation;
  sessionID?: string;
  request?: ConnectionHTTPRequest;
  /** For `fetch`, which uses no declared connection; `connectionID` is empty. */
  fetch?: NetworkRequest;
  /** For the `secret…` operations; `connectionID` is empty. */
  secret?: SecretRequest;
  /** For `openURL`; `connectionID` is empty. */
  url?: string;
  message?: JSONValue;
  /** `false` fails instead of asking the user when access was not granted before. */
  interactive?: boolean;
  /** For `files`; `connectionID` is empty. */
  files?: FilesRequest;
}

export type ConnectionOperation = "request" | "open" | "send" | "close" | "fetch" | "secretGet" | "secretSet" | "secretDelete" | "openURL" | "files";

export interface ConnectionResponse {
  protocolVersion: 1;
  type: "connectionResponse";
  requestID: string;
  result?: JSONValue;
  error?: string;
}

export interface ConnectionEvent {
  protocolVersion: 1;
  type: "connectionEvent";
  connectionID: string;
  sessionID: string;
  event: "message" | "closed";
  message?: JSONValue;
  error?: string;
}

/** A request to a declared local HTTP connection. */
export interface ConnectionHTTPRequest {
  path: string;
  method: HTTPMethod;
  headers?: Record<string, string>;
  body?: string;
  timeoutMs?: number;
}

export type HTTPMethod = "GET" | "POST" | "PUT" | "PATCH" | "DELETE" | "HEAD" | "OPTIONS";

/** An HTTPS request to a host listed in the manifest's `network`. */
export interface NetworkRequest {
  url: string;
  method: HTTPMethod;
  headers?: Record<string, string>;
  body?: string;
  timeoutMs?: number;
}

/** A key in the extension's own Keychain items, and the value for `secretSet`. */
export interface SecretRequest {
  key: string;
  value?: string;
}

/** An action on files the extension received in a drop, done by the app. */
export interface FilesRequest {
  action: FilesAction;
  ids?: string[];
  /** For `open`: a bundle identifier; without one, the default app. */
  app?: string;
  as?: FileEncoding;
  /** For `read`: at most this many bytes (144 KiB), so the answer fits one message. */
  limit?: number;
  /** For `thumbnail`: the edge in points. */
  size?: number;
  /** For `save`: the file's name. */
  name?: string;
  /** For `save`: base64 contents, up to 144 KiB. */
  data?: string;
  /** For `read`: where to start, to read a large file in parts. */
  offset?: number;
  /** For `clipboard`: text to copy instead of files. */
  text?: string;
}

export type FilesAction = "airDrop" | "open" | "reveal" | "preview" | "thumbnail" | "copy" | "move" | "release" | "read" | "save" | "keepCopy" | "share" | "openWith" | "clipboard";

/** For `read`. */
export type FileEncoding = "text" | "base64";

/** notchnotch.json: what an extension is, what it may reach and the settings it asks for. */
export interface ExtensionManifest {
  id: string;
  name: string;
  version: string;
  apiVersion: 1;
  entry: "bundle.js";
  /** `local-network` for loopback HTTP and WebSocket connections, `process` for native helpers, `calendar`, `now-playing`, `battery` and `system` for the app's system capabilities, `file-read` to read and save the files dropped on the extension. */
  permissions: ("local-network" | "process" | "file-read" | "calendar" | "now-playing" | "battery" | "system")[];
  /** Named local destinations: loopback HTTP or WebSocket services and native helpers. */
  connections?: Record<string, ConnectionDefinition>;
  accent?: AccentColorName;
  /** An SF Symbol name, or the file name of a 512×512 PNG in the package's assets/ folder (such as icon.png). */
  icon?: string;
  description?: string;
  /** HTTPS hosts the app may fetch Artwork from for this extension. An exact DNS name or a *.subdomain wildcard (which does not match the bare domain). */
  imageHosts?: string[];
  /** HTTPS hosts the extension may reach with fetch. An exact DNS name or a *.subdomain wildcard (which does not match the bare domain). */
  network?: string[];
  /** Settings NotchNotch asks for, stores and draws natively in Setup. Values reach the extension through getPreferenceValues(). */
  preferences?: ExtensionPreference[];
  /** Store handle of the publisher, such as a GitHub user name. */
  author?: string;
  /** One to three entries from `ExtensionCategory.all`. */
  categories?: ExtensionCategoryName[];
  homepage?: string;
  repository?: string;
  /** An SPDX license expression, such as MIT. */
  license?: string;
}

/** The extension's color in the notch: progress bars, its main button and anything with tone "accent". The app draws each name in a shade tuned for the black notch. Without one, accents are white. */
export type AccentColorName = "orange" | "yellow" | "green" | "mint" | "cyan" | "blue" | "purple" | "pink" | "red";

/** One setting declared in the manifest. The app stores its value, draws the field in Setup and hands the values to the extension when it starts. */
export interface ExtensionPreference {
  name: string;
  type: PreferenceKind;
  title: string;
  description?: string;
  placeholder?: string;
  required?: boolean;
  default?: string | boolean;
  /** Choices for a dropdown. */
  options?: PreferenceOption[];
}

export type PreferenceKind = "text" | "password" | "toggle" | "dropdown";

export interface PreferenceOption {
  value: string;
  title: string;
}

export type ExtensionCategoryName = "Communication" | "Developer Tools" | "Finance" | "Fun" | "Health" | "Media" | "News" | "Productivity" | "Sports" | "System" | "Weather" | "Other";

/** A declared local destination: a loopback HTTP or WebSocket service, or a native helper started over stdio. */
export interface ConnectionDefinition {
  transport: ConnectionTransport;
  endpoint?: string;
  executable?: string;
  arguments?: string[];
}

export type ConnectionTransport = "http" | "websocket" | "stdio";
